        content = resp.get("delta") or resp.get("content_block") or {}
        if (stop_reason := content.get("stop_reason")) is not None:
            stop_reason = "length" if stop_reason == "max_tokens" else "stop"

        # Anthropic's block `index` counts every content block (text and tool_use), whereas
        # OpenAI's tool call `index` counts only tool calls; the caller supplies the latter.
        tool_call_index = resp.get("_tool_call_index", 0)

