def _sse(event: dict[str, Any]) -> bytes:
    return f"data: {json.dumps(event)}\n".encode()


def _tool_use_sse(block_index: int, tool_id: str, arguments: str) -> list[bytes]:
    return [
        _sse({
            "type": "content_block_start",
            "index": block_index,
            "content_block": {"type": "tool_use", "id": tool_id, "name": "get_weather"},
        }),
        _sse({
            "type": "content_block_delta",
            "index": block_index,
            "delta": {"type": "input_json_delta", "partial_json": arguments},
        }),
        _sse({"type": "content_block_stop", "index": block_index}),
    ]


