            },
        }),
    ]
    if leading_text:
        resp += [
            _sse({
                "type": "content_block_start",
                "index": 0,
                "content_block": {"type": "text", "text": ""},
            }),
            _sse({
                "type": "content_block_delta",
                "index": 0,
                "delta": {"type": "text_delta", "text": "Checking both."},
            }),
            _sse({"type": "content_block_stop", "index": 0}),
        ]
    # Anthropic's content block index counts the text block, so tool blocks start at 1 then
    first_tool_block = 1 if leading_text else 0
    resp += _tool_use_sse(first_tool_block, "toolu_001", '{"location": "Paris"}')
    resp += _tool_use_sse(first_tool_block + 1, "toolu_002", '{"location": "Tokyo"}')
    resp += [
        _sse({
            "type": "message_delta",
            "delta": {"stop_reason": "tool_use"},
            "usage": {"output_tokens": 15},
        }),
        _sse({"type": "message_stop"}),
    ]

    with mock.patch("aiohttp.ClientSession.post", return_value=MockAsyncStreamingResponse(resp)):
        provider = AnthropicProvider(EndpointConfig(**chat_config()))
